+// PRIVATE DIAGNOSTIC OVERLAY ONLY. These predicates observe operand families;
+// they never select the arithmetic above. No elapsed-time claims are valid for
+// this instrumented module. Each drain retains first16 triplets per family.
+const DISPATCH_PROBE_SAMPLE_LIMIT: usize = 16;
+
+struct WasmFmaDispatchProbe {
+    counts: [u64; 8],
+    lengths: [usize; 7],
+    samples: [[[u64; 3]; DISPATCH_PROBE_SAMPLE_LIMIT]; 7],
+}
+
+impl WasmFmaDispatchProbe {
+    const fn new() -> Self {
+        Self {
+            counts: [0; 8],
+            lengths: [0; 7],
+            samples: [[[0; 3]; DISPATCH_PROBE_SAMPLE_LIMIT]; 7],
+        }
+    }
+}
+
+thread_local! {
+    static WASM_FMA_DISPATCH_PROBE: std::cell::RefCell<WasmFmaDispatchProbe> =
+        const { std::cell::RefCell::new(WasmFmaDispatchProbe::new()) };
+}
+
+#[allow(clippy::float_cmp)]
+#[cfg_attr(not(any(target_arch = "wasm32", test)), allow(dead_code))]
+fn wasm_fma_dispatch_probe_family(a: f64, b: f64, c: f64) -> usize {
+    if is_zero_product(a, b, c) {
+        if a == 0.0 {
+            if b == 0.0 { 3 } else { 1 }
+        } else {
+            2
+        }
+    } else if c == 0.0 && a != 0.0 && b != 0.0 && a.is_finite() && b.is_finite() {
+        4
+    } else if (a.abs() == 1.0 || b.abs() == 1.0)
+        && a != 0.0
+        && b != 0.0
+        && a.is_finite()
+        && b.is_finite()
+        && c.is_finite()
+    {
+        5
+    } else if in_emulated_range(a, b, c) {
+        6
+    } else {
+        7
+    }
+}
+
+#[cfg_attr(not(any(target_arch = "wasm32", test)), allow(dead_code))]
+fn record_wasm_fma_dispatch_probe(a: f64, b: f64, c: f64) {
+    let family = wasm_fma_dispatch_probe_family(a, b, c);
+    WASM_FMA_DISPATCH_PROBE.with(|slot| {
+        let mut probe = slot.borrow_mut();
+        probe.counts[0] = probe.counts[0]
+            .checked_add(1)
+            .expect("diagnostic count overflow");
+        probe.counts[family] = probe.counts[family]
+            .checked_add(1)
+            .expect("diagnostic count overflow");
+        let index = probe.lengths[family - 1];
+        if index < DISPATCH_PROBE_SAMPLE_LIMIT {
+            probe.samples[family - 1][index] = [a.to_bits(), b.to_bits(), c.to_bits()];
+            probe.lengths[family - 1] += 1;
+        }
+    });
+}
+
+/// PRIVATE DIAGNOSTIC ONLY: drain total/seven disjoint counts, seven sample
+/// lengths, then each family's firstN raw operand-bit triplets in family order.
+/// All integers cross the temporary WASM binding without floating conversion.
+#[must_use]
+pub fn take_wasm_fma_dispatch_probe() -> Vec<u64> {
+    let probe = WASM_FMA_DISPATCH_PROBE.with(|slot| slot.replace(WasmFmaDispatchProbe::new()));
+    let mut result = Vec::with_capacity(15 + 7 * DISPATCH_PROBE_SAMPLE_LIMIT * 3);
+    result.extend_from_slice(&probe.counts);
+    result.extend(probe.lengths.iter().map(|&length| length as u64));
+    for family in 0..7 {
+        for triplet in &probe.samples[family][..probe.lengths[family]] {
+            result.extend_from_slice(triplet);
+        }
+    }
+    result
+}
